      if (r.matches(prefix, prefixIsDir)) ignored = !r.negated;
    }
  }
  return ignored;
}

/// Would pub's payload (git-tracked files ∩ .pubignore) carry [file]?
bool _publishedByPub(String file) =>
    !_ignoredByPubIgnore(_pubIgnoreRules(), file, false);

