const _stageMarker = 'rsync -a';
const _overridesFile = 'pubspec_overrides.yaml';

class _Filter {
  _Filter(this.include, this.pattern)
    : dirOnly = pattern.endsWith('/'),
      anchored = pattern.contains('/') {
    final unanchored = pattern.endsWith('/')
